cd /workspace && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/order_summary.xlsx');
const ws = wb.Sheets['Orders'];
const data = XLSX.utils.sheet_to_json(ws);

// Total orders
console.log('📊 ORDER SUMMARY');
console.log('================');
console.log('Total Orders:', data.length);

// Status breakdown
const statuses = {};
data.forEach(r => { statuses[r.Status] = (statuses[r.Status]||0) + 1; });
console.log('\n📋 Status Breakdown:');
Object.entries(statuses).forEach(([k,v]) => console.log('  ', k + ':', v));

// Customer breakdown
const customers = {};
data.forEach(r => { customers[r.Customer] = (customers[r.Customer]||0) + 1; });
console.log('\n👤 Orders by Customer:');
Object.entries(customers).sort((a,b) => b[1]-a[1]).forEach(([k,v]) => console.log('  ', k + ':', v));

// Revenue
const totals = data.map(r => r['Total Paid']);
const totalRev = totals.reduce((a,b) => a+b, 0);
const confirmedRev = data.filter(r => r.Status === 'confirmed').map(r => r['Total Paid']).reduce((a,b) => a+b, 0);
console.log('\n💰 Financial Summary:');
console.log('  Total Revenue (all):', '$' + totalRev);
console.log('  Total Revenue (confirmed only):', '$' + confirmedRev);
console.log('  Average Order Value:', '$' + (totalRev / data.length).toFixed(2));
console.log('  Min Order:', '$' + Math.min(...totals));
console.log('  Max Order:', '$' + Math.max(...totals));

// Date range
const dates = [...new Set(data.map(r => r.Date))].sort();
console.log('\n📅 Date Range:', dates.join(', '));

// Top products
const products = {};
data.forEach(r => {
  r.Items.split(', ').forEach(item => {
    products[item] = (products[item]||0) + 1;
  });
});
console.log('\n🛒 Top Products (by frequency):');
Object.entries(products).sort((a,b) => b[1]-a[1]).forEach(([k,v]) => console.log('  ', k + ':', v));
"
